def syscall_endpoint_send(self, caller: int, endpoint_id: int,
                          payload: dict, timeout: float = 5.0) -> bool:
    """Send a message to an endpoint. Caller must have send capability."""
    self._validate_task(caller)
    if not self._check_cap(caller, "endpoint", endpoint_id, "send"):
        raise KernelError("No endpoint:send capability", Err.PERMISSION_DENIED)
    ep = self._endpoints.get(endpoint_id)
    if not ep:
        raise KernelError(f"Endpoint {endpoint_id} not found", Err.INVALID_ENDPOINT)
    self._seq += 1
    msg = Message(type="call", sender=caller, payload=payload, seq=self._seq)
    try:
        ep.queue.put(msg, timeout=timeout)
        return True
    except queue.Full:
        raise KernelError("Endpoint queue full", Err.TIMEOUT)

def syscall_endpoint_recv(self, caller: int, endpoint_id: int,
                          timeout: float = 5.0) -> Optional[Message]:
    """Receive from an endpoint. Caller must be owner or have recv capability."""
    self._validate_task(caller)
    if not self._check_cap(caller, "endpoint", endpoint_id, "recv"):
        raise KernelError("No endpoint:recv capability", Err.PERMISSION_DENIED)
    ep = self._endpoints.get(endpoint_id)
    if not ep:
        raise KernelError(f"Endpoint {endpoint_id} not found", Err.INVALID_ENDPOINT)
    try:
        return ep.queue.get(timeout=timeout)
    except queue.Empty:
        return None

def syscall_memory_read(self, caller: int, region_id: int,
                        offset: int, length: int) -> bytes:
    """Read from a memory region."""
    with self._lock:
        self._validate_task(caller)
        region = self._regions.get(region_id)
        if not region:
            raise KernelError(f"Region {region_id} not found", Err.INVALID_REGION)
        if caller not in region.mapped_tasks:
            raise KernelError("Region not mapped", Err.PERMISSION_DENIED)
        if not self._check_cap(caller, "memory", region_id, "read"):
            raise KernelError("No memory:read capability", Err.PERMISSION_DENIED)
        if offset < 0 or offset + length > region.size:
            raise KernelError("Out of bounds", Err.INVALID_REGION)
        return bytes(region.data[offset:offset + length])

